DROP TABLE IF EXISTS `t_role_permission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_role_permission` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增',
  `role_type` tinyint NOT NULL COMMENT '角色类型：1=业务角色 2=API角色',
  `role_id` bigint unsigned NOT NULL COMMENT '对应业务角色 id（t_biz_role.id）或 API 角色 id（t_api_role.id）',
  `perm_id` bigint unsigned NOT NULL COMMENT '关联权限主表 id（t_permission.id）',
  `is_enabled` tinyint NOT NULL DEFAULT '1' COMMENT '启用标记：1启用 0禁用',
  `expire_at` datetime DEFAULT NULL COMMENT '有效期，NULL=长期有效',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_role_permission` (`role_type`,`role_id`,`perm_id`),
  KEY `idx_role_permission_perm` (`perm_id`)
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='角色-权限关联表：role_type(1业务/2API)+role_id 定位角色，perm_id→t_permission.id；唯一(role_type,role_id,perm_id)，用 role_type 区分两套角色、权限主表全局复用';
/*!40101 SET character_set_client = @saved_cs_client */;

